class Solution {
    public int[] beautifulArray(int n){
        List<Integer> values=new ArrayList<>();
        values.add(1);
        while(values.size()<n){
            List<Integer> next=new ArrayList<>();
            for(int x:values)if(2*x-1<=n)next.add(2*x-1);
            for(int x:values)if(2*x<=n)next.add(2*x);
            values=next;
        }
        return values.stream().mapToInt(Integer::intValue).toArray();
    }
}

code.kotlin:
class Solution {
    fun beautifulArray(n:Int):IntArray{
        var values=listOf(1);
        while(values.size<n){
            val next=mutableListOf<Int>();
            for(x in values)if(2*x-1<=n)next.add(2*x-1);
            for(x in values)if(2*x<=n)next.add(2*x);
            values=next
        };
        return values.toIntArray()
    }
}

code.cpp:
class Solution {
    public: vector<int> beautifulArray(int n){
        vector<int> values{
            1
        };
        while((int)values.size()<n){
            vector<int> next;
            for(int x:values)if(2*x-1<=n)next.push_back(2*x-1);
            for(int x:values)if(2*x<=n)next.push_back(2*x);
            values.swap(next);
        }
        return values;
    }
};
